from lib import *
import numpy as np, itertools
names=['L','Lb','R','Rb']
# character values on generators: det of V rep, det W rep, M0 char
Q0,_=compl((0,0))
def m0(e): return Q0.conj().T@Dmat_cochain((0,0),e)@Q0
rows=[]
for n in names:
    e=GENS[n]
    rows.append((n,np.round(np.linalg.det(Vrep(e)),4),np.round(np.linalg.det(Wrep(e)),4),np.round(np.linalg.eigvals(m0(e)),4)))
for r in rows: print(r)
# order of subgroup of U(1)^k generated by (detV,detW,m0 char1) on gens (lower bound on |E^ab| if these are characters of E)
def key(v): return tuple(np.round(np.angle(v)/(2*np.pi)%1,4)%1)
vecs=[]
for n in names:
    e=GENS[n];ev=sorted(np.linalg.eigvals(m0(e)),key=lambda z:(np.angle(z)))
    vecs.append(np.array([np.linalg.det(Vrep(e)),np.linalg.det(Wrep(e)),ev[0]]))
seen={key(np.ones(3)):np.ones(3)};fr=[np.ones(3)]
while fr:
    new=[]
    for v in fr:
        for g in vecs:
            w=v*g;k=key(w)
            if k not in seen: seen[k]=w;new.append(w)
    fr=new
print("abelian group generated by (detV,detW,mu) on the generators, order:",len(seen))
# E8 central kernel
import cmath
z6=cmath.exp(2j*cmath.pi/6);w3=cmath.exp(2j*cmath.pi/3)
# 248 = (35,1,1)+(1,3,1)+(20,2,1)+(1,1,8)+(15b,1,3)+(6,2,3)+(15,1,3b)+(6b,2,3b); central action alpha in mu6,beta=+-1,gamma in mu3
def act(al,be,ga):
    return [al**3*be, al**-2*ga, al*be*ga, al**2*ga**-1, al**-1*be*ga**-1]
ker=[]
for k in range(6):
    for be in (1,-1):
        for j in range(3):
            al=z6**k;ga=w3**j
            if all(abs(x-1)<1e-9 for x in act(al,be,ga)): ker.append((k,be,j))
print("kernel of Z6xZ2xZ3 on 248 (alpha=z6^k,beta,gamma=w3^j):",ker)
print("generated by (1,-1,1)? element (zeta6,-1,omega):",(1,-1,1) in ker)
# puncture -I6 = alpha=z6^3 on 6 ; acts on the 20,2,1 as alpha^3 beta
print("(-I6,1,1) on (20,2,1):",z6**9*1," on (6,2,3): ",z6**3*1*1)
